const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const aoi = ee.Geometry.Polygon([[
        [26.7, -18.0],
        [26.7, -16.2],
        [29.1, -16.2],
        [29.1, -18.0]
    ]], null, false);
    const startDate2018 = '2018-12-01';
    const endDate2018 = '2018-12-31';
    const startDate2019 = '2019-12-01';
    const endDate2019 = '2019-12-31';
    const SCALE = 3000;

    // 2. Data Acquisition & Processing Function
    // Cloud masking function for Sentinel-2
    function maskS2clouds(image) {
        const qa = image.select('QA60');
        // Bits 10 and 11 are clouds and cirrus, respectively.
        const cloudBitMask = 1 << 10;
        const cirrusBitMask = 1 << 11;
        // Both flags should be set to zero, indicating clear conditions.
        const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
            .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
        return image.updateMask(mask).divide(10000)
            .copyProperties(image, ["system:time_start"]);
    }

    // Function to calculate NDWI and create a water mask
    function getWaterMask(image) {
        // NDWI = (Green - NIR) / (Green + NIR) -> Sentinel-2 B3, B8
        const ndwi = image.normalizedDifference(['B3', 'B8']).rename('ndwi');
        // A threshold of 0 is a common starting point for separating water from land.
        return ndwi.gt(0).rename('water');
    }

    // Function to get water pixel count for a given period
    async function getWaterPixelCount(startDate, endDate, aoi) {
        let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
            .filterBounds(aoi)
            .filterDate(startDate, endDate);

        const initialSize = collection.size().getInfo();
        if (initialSize === 0) {
            return { pixelCount: null, imageCount: 0 };
        }

        const processedCollection = collection.map(maskS2clouds);
        const composite = processedCollection.median(); // Create a cloud-free composite
        const waterMask = getWaterMask(composite);

        const countDict = waterMask.reduceRegion({
            reducer: ee.Reducer.sum(), // Count pixels where water=1
            geometry: aoi,
            scale: SCALE,
            maxPixels: 1e9
        });

        // Use .get() to retrieve the value, then await getInfo()
        const count = ee.Number(countDict.get('water')).getInfo();
        return { pixelCount: count, imageCount: initialSize };
    }

    // 3. Calculation
    const results2018 = await getWaterPixelCount(startDate2018, endDate2018, aoi);
    const results2019 = await getWaterPixelCount(startDate2019, endDate2019, aoi);

    const count2018 = results2018.pixelCount;
    const count2019 = results2019.pixelCount;

    // 4. Validation & Final Answer
    console.log(`Images Found (Dec 2018): ${results2018.imageCount}`);
    console.log(`Images Found (Dec 2019): ${results2019.imageCount}`);

    if (results2018.imageCount === 0 || results2019.imageCount === 0) {
        console.log("No images found for one or both periods.");
        console.log("C1");
        return;
    }

    console.log(`Water Pixel Count (2018): ${count2018}`);
    console.log(`Water Pixel Count (2019): ${count2019}`);

    if (count2018 === null || count2019 === null) {
        console.log("Calculation failed, could not derive a valid pixel count.");
        console.log("C3");
    } else if (count2018 === 0 || count2019 === 0) {
        console.log("No valid water pixels found after processing.");
        console.log("C2");
    } else if (count2019 > count2018) {
        console.log("Conclusion: Water levels were higher in Dec 2019 than Dec 2018.");
        console.log("A");
    } else {
        console.log("Conclusion: Water levels were NOT higher in Dec 2019 than Dec 2018.");
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during Earth Engine initialization or analysis.');
        console.error(e);
        console.log("D");
    }
}

initEE();
